function transpose(matrix: number[][]): number[][] {
  const m = matrix.length, n = matrix[0].length;
  const out = Array.from({ length: n }, () => new Array<number>(m));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) out[j][i] = matrix[i][j];
  }
  return out;
}

